package mod.cdv.tnpc.tactical;
import fixture.*;import java.util.*;import java.lang.ref.*;import mod.cdv.tnpc.entity.AutoGunOperator;import net.minecraft.world.item.ItemStack;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.crafting.*;import net.minecraft.core.BlockPos;import net.minecraft.world.level.block.CropBlock;import me.danialisntcool.factionfriction.data.FactionManager;import dev.zomboid.clans.Companions16;
public class AdvancedChecks{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static AutoGunOperator npc(World w)throws Exception{AutoGunOperator n=new AutoGunOperator(w);Social.init(n);return n;}
 public static void main(String[]args)throws Exception{
  World w=new World();AutoGunOperator smith=npc(w);smith.bag.add(new ItemStack("minecraft:iron_ingot",2));smith.bag.add(new ItemStack("minecraft:stick",1));w.recipes.custom.add(new RecipeManager.Holder(new ShapedRecipe()));ok(!CraftPlanner.craft(smith)&&smith.bag.get(0).count==2,"three-high real recipe requires crafting table");w.blocks.put(new BlockPos(1,0,0),"minecraft:crafting_table");ok(CraftPlanner.craft(smith),"generic planner executes valid non-hardcoded sword recipe");ok(smith.bag.size()==1&&smith.bag.get(0).id.equals("minecraft:iron_sword"),"exact two iron and stick consumed, actual output collected");smith.bag.add(new ItemStack("minecraft:iron_ingot",2));smith.bag.add(new ItemStack("minecraft:stick",1));ok(!CraftPlanner.craft(smith)&&smith.bag.get(1).count==2,"does not craft duplicate tools it already owns");
  World f=new World();AutoGunOperator farmer=npc(f);BlockPos cropPos=new BlockPos(0,0,0);CropBlock wheat=new CropBlock();BlockState mature=wheat.defaultBlockState();mature.age=7;f.blocks.put(cropPos,mature);Social.Memory fm=Social.mem(farmer);fm.work=cropPos;fm.workKind="farm";Tasks.farm(farmer,fm,0);ok(f.getBlockState(cropPos).age==0&&f.getBlockState(cropPos).getBlock() instanceof CropBlock,"mature crop harvested and replanted");ok(farmer.bag.stream().anyMatch(s->s.id.equals("minecraft:wheat")&&s.count==2)&&farmer.bag.stream().anyMatch(s->s.id.equals("minecraft:wheat_seeds")&&s.count==1),"actual crop drops collected and one seed used");fm.work=cropPos;Tasks.farm(farmer,fm,40);ok(farmer.bag.stream().filter(s->s.id.equals("minecraft:wheat")).mapToInt(s->s.count).sum()==2,"immature crop left untouched");
  World g=new World();AutoGunOperator victim=npc(g),witness=npc(g);victim.tag.putInt("soc_kind",1);victim.tag.putInt("np15_parts",1);victim.tag.putDouble("np15_hp_body",12);witness.x=10;Player offender=new Player(g);offender.x=1;Social.hurt(victim,new SocialChecks.Source(offender),2,true);String key="soc_heard_"+offender.uuid;ok(witness.tag.getInt(key)==-8,"nearby witness learns the observed offense");AutoGunOperator listener=npc(g);listener.x=14;offender.x=100;g.now=400;Social.environment(witness,Social.mem(witness),400);ok(listener.tag.getInt(key)==-8,"NPCs gossip even when the offending player is absent");
  World invWorld=new World();AutoGunOperator companion=npc(invWorld);Player owner=new Player(invWorld),visitor=new Player(invWorld);FactionManager.Faction faction=new FactionManager.Faction();invWorld.server.manager.factions.put(faction.id,faction);invWorld.server.manager.playerFaction.put(owner.uuid,faction.id);invWorld.server.manager.playerFaction.put(visitor.uuid,faction.id);Companions16.enroll(invWorld.server,companion.uuid,owner,"Ally");CompanionInventory container=new CompanionInventory(companion,owner);ok(container.stillValid(owner)&&!container.stillValid(visitor),"one inventory view belongs to one authorized player");Object menu=new Object();owner.containerMenu=menu;Social.mem(companion).inventoryPlayer=new WeakReference<>(owner);Social.mem(companion).inventoryMenu=menu;CompanionInventory.open(companion,visitor);ok(Social.mem(companion).inventoryPlayer.get()==owner&&visitor.messages==1,"second viewer is refused instead of creating a stale duplicating snapshot");owner.containerMenu=new Object();ok(!CompanionInventory.active(companion),"inventory lock released after owner closes menu");
  BlockPos near=new BlockPos(1,0,0);invWorld.blocks.put(near,"minecraft:barrel");invWorld.storage.put(near,new Storage());ok(near.equals(Conversation.depotPos(companion,owner)),"storage authorization falls back to nearest valid nearby work station");
  System.out.println("NPC_GENERIC_CRAFT_FARM_GOSSIP_INVENTORY_CHECKS="+checks);
 }
}
